        void *new_data = realloc(list->data, new_capacity * list->elem_size);
        if (!new_data) { fputs("Clair runtime error: out of memory while growing list\n", stderr); exit(EXIT_FAILURE); }
        list->data = new_data;
        list->capacity = new_capacity;
