static uint64_t clair_rt_dict_hash(const char *key) {          /* FNV-1a */
    uint64_t h = 14695981039346656037ULL;
    for (const unsigned char *p = (const unsigned char *)key; *p; p++) h = (h ^ *p) * 1099511628211ULL;
    return h;
}

/* where index goes in the table (open addressing: the next free slot) */
static void clair_rt_dict_slot_put(ClairDict dict, size_t index) {
    size_t mask = dict->slot_count - 1, s = (size_t)clair_rt_dict_hash(dict->keys[index]) & mask;
    while (dict->slots[s] >= 0) s = (s + 1) & mask;
    dict->slots[s] = (int64_t)index;
}

/* the table holds at least twice as many slots as keys */
static void clair_rt_dict_reindex(ClairDict dict) {
    size_t count = 16;
    while (count < dict->len * 2) count *= 2;
    free(dict->slots);
    dict->slots = malloc(count * sizeof(*dict->slots));
    if (!dict->slots) clair_rt_dict_runtime_error("out of memory while indexing a dictionary");
    for (size_t s = 0; s < count; s++) dict->slots[s] = -1;
    dict->slot_count = count;
    for (size_t i = 0; i < dict->len; i++) clair_rt_dict_slot_put(dict, i);
}

/* the position of key, or -1 */
static int64_t clair_rt_dict_find(ClairDict dict, const char *key) {
    if (!dict->slots) {
        for (size_t i = 0; i < dict->len; i++) if (strcmp(dict->keys[i], key) == 0) return (int64_t)i;
        return -1;
    }
    size_t mask = dict->slot_count - 1, s = (size_t)clair_rt_dict_hash(key) & mask;
    while (dict->slots[s] >= 0) {
        if (strcmp(dict->keys[dict->slots[s]], key) == 0) return dict->slots[s];
        s = (s + 1) & mask;
    }
    return -1;
}

static void *clair_rt_dict_at(ClairDict dict, const char *key) {
    if (!dict) clair_rt_dict_runtime_error("null dictionary");
    if (!key) clair_rt_dict_runtime_error("null dictionary key");
    int64_t i = clair_rt_dict_find(dict, key);
    if (i >= 0) return (unsigned char *)dict->values + ((size_t)i * dict->elem_size);
    fprintf(stderr, "Clair runtime error: dictionary key '%s' not found\n", key);
    exit(EXIT_FAILURE);
}

static void *clair_rt_dict_set_slot(ClairDict dict, const char *key) {
    if (!dict) clair_rt_dict_runtime_error("null dictionary");
    if (!key) clair_rt_dict_runtime_error("null dictionary key");
    if (dict->elem_size == 0) clair_rt_dict_runtime_error("invalid dictionary value size");
    int64_t found = clair_rt_dict_find(dict, key);
    if (found >= 0) return (unsigned char *)dict->values + ((size_t)found * dict->elem_size);
    if (dict->len == dict->capacity) {
        size_t new_capacity = dict->capacity ? dict->capacity * 2 : 4;
        if (new_capacity < dict->capacity || new_capacity > SIZE_MAX / sizeof(*dict->keys) ||
            new_capacity > SIZE_MAX / dict->elem_size) {
            clair_rt_dict_runtime_error("dictionary capacity overflow");
        }
        const char **new_keys = realloc(dict->keys, new_capacity * sizeof(*new_keys));
        if (!new_keys) clair_rt_dict_runtime_error("out of memory while growing dictionary keys");
        dict->keys = new_keys;
        void *new_values = realloc(dict->values, new_capacity * dict->elem_size);
        if (!new_values) clair_rt_dict_runtime_error("out of memory while growing dictionary values");
        dict->values = new_values;
        dict->capacity = new_capacity;
    }
    size_t index = dict->len++;
    size_t key_size = strlen(key) + 1;               /* V0.54: its own copy of the key */
    char *copy = malloc(key_size);
    if (!copy) clair_rt_dict_runtime_error("out of memory while copying a dictionary key");
    memcpy(copy, key, key_size);
    dict->keys[index] = copy;
    if (dict->slots && dict->len * 2 <= dict->slot_count) clair_rt_dict_slot_put(dict, index);
    else if (dict->len >= 8) clair_rt_dict_reindex(dict);
    return (unsigned char *)dict->values + (index * dict->elem_size);
}

static ClairDict clair_rt_dict_make(const char *const *keys, const void *values, size_t len, size_t elem_size) {
    if (elem_size == 0) clair_rt_dict_runtime_error("invalid dictionary value size");
    ClairDict result = malloc(sizeof(*result));
    if (!result) clair_rt_dict_runtime_error("out of memory while creating dictionary");
    result->keys = NULL;
    result->values = NULL;
    result->len = 0;
    result->capacity = 0;
    result->elem_size = elem_size;
    result->slots = NULL;
    result->slot_count = 0;
    clair_rt_track_dict(result);
    for (size_t i = 0; i < len; i++) {
        void *slot = clair_rt_dict_set_slot(result, keys[i]);
        memcpy(slot, (const unsigned char *)values + (i * elem_size), elem_size);
    }
    return result;
}

